// ─── File: AuditLogDemo.java ───
// Tamper-evident audit log: hash chain + verify + tamper detection + signed anchor + query.
// Each class below would be its own file in a real project.
package com.bank.audit;

import java.util.*;
import java.util.logging.*;

public class AuditLogDemo {

    private static final Logger log = Logger.getLogger("Audit");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        HashChainLog auditLog = new HashChainLog();
        CheckpointSigner signer = new CheckpointSigner();

        // Append sensitive banking actions — each chains to the previous.
        auditLog.append("OFFICER-7", "VIEW_STATEMENT", "SAV2001", "viewed Rajesh statement");
        auditLog.append("OFFICER-7", "CHANGE_LIMIT", "CUR3001", "raised Priya limit to 500000");
        auditLog.append("RAJESH", "TRANSFER", "SAV2001", "transferred Rs.50000 to CUR3001");

        // Periodic signed anchor of the chain head (catches whole-chain rewrites).
        String signedHead = signer.sign(auditLog.head());
        log.info(() -> "ANCHOR: signed chain head = " + signedHead);

        // Verify integrity — intact chain passes.
        log.info(() -> "verify (intact) = " + auditLog.verify());

        // Query by actor (designed-in access pattern).
        log.info(() -> "records by OFFICER-7 = " + auditLog.queryByActor("OFFICER-7").size());

        // Someone tampers with an old record's content → chain breaks, detectable.
        auditLog.tamperForDemo(1, "raised Priya limit to 5000000");   // malicious edit
        boolean ok = auditLog.verify();
        log.severe(() -> "verify (after tamper) = " + ok + " → tampering DETECTED");

        // And the signed anchor no longer matches the current (rewritten) head.
        log.severe(() -> "anchor check = " + signer.matches(signedHead, auditLog.head())
                + " → whole-chain rewrite also detectable");
    }
}

// ─── model/AuditRecord.java ───
class AuditRecord {
    final long seq; final long ts; final String actor, action, entity, detail;
    String prevHash, hash;                      // prevHash links to prior record
    AuditRecord(long seq, long ts, String actor, String action, String entity, String detail) {
        this.seq = seq; this.ts = ts; this.actor = actor;
        this.action = action; this.entity = entity; this.detail = detail;
    }
    // content hashed = record fields (incl. seq + ts, so reorder is detectable) + prevHash
    String payload() { return seq + "|" + ts + "|" + actor + "|" + action + "|" + entity + "|" + detail; }
}

// ─── chain/HashChainLog.java ───  hash(current_record + previous_hash)
class HashChainLog {
    private static final Logger log = Logger.getLogger("Audit");
    private final List<AuditRecord> records = new ArrayList<>();   // append-only / WORM in prod
    private static final String GENESIS = "0".repeat(64);

    void append(String actor, String action, String entity, String detail) throws Exception {
        long seq = records.size();
        String prev = records.isEmpty() ? GENESIS : records.get(records.size() - 1).hash;
        AuditRecord r = new AuditRecord(seq, System.currentTimeMillis(), actor, action, entity, detail);
        r.prevHash = prev;
        r.hash = sha256(r.payload() + prev);     // THE CHAIN: content + previous hash
        records.add(r);
        log.info(() -> "appended seq=" + r.seq + " " + action + " hash=" + r.hash.substring(0, 12) + "...");
    }

    // Walk the chain, recompute each hash — first mismatch = tamper location.
    boolean verify() throws Exception {
        String prev = GENESIS;
        for (AuditRecord r : records) {
            if (!r.prevHash.equals(prev)) return false;                 // broken linkage
            if (!r.hash.equals(sha256(r.payload() + prev))) return false; // content changed
            prev = r.hash;
        }
        return true;
    }

    String head() { return records.isEmpty() ? GENESIS : records.get(records.size() - 1).hash; }

    List<AuditRecord> queryByActor(String actor) {
        return records.stream().filter(r -> r.actor.equals(actor)).toList();  // indexed in prod
    }

    // DEMO ONLY: simulate a privileged tamperer editing old content (without re-hashing).
    void tamperForDemo(int index, String newDetail) {
        AuditRecord r = records.get(index);
        records.set(index, new AuditRecord(r.seq, r.ts, r.actor, r.action, r.entity, newDetail) {{
            prevHash = r.prevHash; hash = r.hash;   // old hash kept → will fail verification
        }});
    }

    private String sha256(String s) throws Exception {
        var md = java.security.MessageDigest.getInstance("SHA-256");
        byte[] d = md.digest(s.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        StringBuilder sb = new StringBuilder();
        for (byte b : d) sb.append(String.format("%02x", b));
        return sb.toString();
    }
}

// ─── anchor/CheckpointSigner.java ───  sign the chain head so rewrites are caught
class CheckpointSigner {
    // real impl: sign with a private key in an HSM/secrets manager; store in WORM/notary.
    String sign(String head) { return "SIG(" + head.substring(0, 12) + ")"; }
    boolean matches(String signedHead, String currentHead) {
        return signedHead.equals("SIG(" + currentHead.substring(0, 12) + ")");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
